	-- Nhận biết PC hay điện thoại rồi chọn kích cỡ phù hợp
	local function getViewport()
		local cam = workspace.CurrentCamera
		local t0 = os.clock()
		while (not cam or cam.ViewportSize.Y < 2) and os.clock() - t0 < 3 do
			task.wait()
			cam = workspace.CurrentCamera
		end
		return cam and cam.ViewportSize or Vector2.new(1920, 1080)
	end
	local function isPC()
		local ok, pc = pcall(function()
			if UIS.KeyboardEnabled and UIS.MouseEnabled then return true end
			return not UIS.TouchEnabled
		end)
		return ok and pc
	end
	local INTRO_SCALE = INTRO_SCALE_MOBILE
	if isPC() then
		INTRO_SCALE = INTRO_SCALE_PC
		if PC_AUTO_FIT then
			local vp = getViewport()
			local fit = math.min(vp.X / 1920, vp.Y / 1080)
			INTRO_SCALE = math.clamp(INTRO_SCALE_PC * fit, PC_MIN_SCALE, PC_MAX_SCALE)
		end
	end
