	local PAPER_B64 = ""

	--============================================================
	-- HELPERS
	--============================================================
	local function b64decode(data)
		local ok, out = pcall(function()
			local f = (crypt and (crypt.base64decode or (crypt.base64 and crypt.base64.decode)))
				or base64_decode
				or (base64 and base64.decode)
				or (syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode)
			if f then return f(data) end
		end)
		if ok and type(out) == "string" and #out > 100 then return out end
		local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
		local map = {}
		for i = 1, 64 do map[string.byte(alphabet, i)] = i - 1 end
		data = string.gsub(data, "[^%w%+/]", "")
		local res, n = {}, 0
		local byte, char, floor = string.byte, string.char, math.floor
		for i = 1, #data, 4 do
			local a, b, c, d = byte(data, i, i + 3)
			a, b = map[a], map[b]
			c = c and map[c]
			d = d and map[d]
			local v = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
			local b1, b2, b3 = floor(v / 65536) % 256, floor(v / 256) % 256, v % 256
			n = n + 1
			if d then
				res[n] = char(b1, b2, b3)
			elseif c then
				res[n] = char(b1, b2)
			else
				res[n] = char(b1)
			end
		end
		return table.concat(res)
	end

	-- Ảnh nhúng -> writefile -> getcustomasset (lỗi thì trả về nil)
	local function embeddedAsset(file, data)
		local asset
		pcall(function()
			if isfile and isfile(file) then asset = getcustomasset(file) end
		end)
		if asset then return asset end
		local ok, bytes = pcall(b64decode, data)
		if not ok or type(bytes) ~= "string" or #bytes < 100 then return nil end
		pcall(function() writefile(file, bytes) end)
		pcall(function() asset = getcustomasset(file) end)
		return asset
	end

	-- Tải file từ link -> getcustomasset (có cache bằng writefile)
	local function loadUrlAsset(url, file)
		if not url or url == "" then return nil end
		local asset
		pcall(function()
			if isfile and isfile(file) then asset = getcustomasset(file) end
		end)
		if asset then return asset end
		local ok, data = pcall(function() return game:HttpGet(url) end)
		if ok and data and #data > 1000 then
			pcall(function() writefile(file, data) end)
			pcall(function() asset = getcustomasset(file) end)
		end
		return asset
	end

