	local function playTimeline(segments, options, onDone)
    options = options or {}
    local runService = game:GetService("RunService")
    local soundService = game:GetService("SoundService")
    local players = game:GetService("Players")
    local playerGui = options.target or players.LocalPlayer:WaitForChild("PlayerGui")
    local globalEnv = _G
    pcall(function()
        if type(getgenv) == "function" then
            local candidate = getgenv()
            if type(candidate) == "table" then globalEnv = candidate end
        end
    end)

    local KEY = "__GHOST_DUEL_INTRO_PLAYBACK_V1"
    pcall(function()
        local previous = globalEnv[KEY]
        if type(previous) == "table" and type(previous.stop) == "function" then previous.stop() end
    end)

    local state = {stopped = false, objects = {}, sounds = {}, soundLoads = {}, pending = {}}
    pcall(function() globalEnv[KEY] = state end)

    local function destroySound(id)
        local con = state.soundLoads[id]
        if con then pcall(function() con:Disconnect() end); state.soundLoads[id] = nil end
        local sound = state.sounds[id]
        state.sounds[id] = nil
        if sound then
            pcall(function() sound:Stop() end)
            pcall(function() sound:Destroy() end)
        end
    end
    local function clearSegment()
        local soundIds = {}
        for id in pairs(state.sounds) do soundIds[#soundIds + 1] = id end
        for _, id in ipairs(soundIds) do destroySound(id) end
        for _, object in pairs(state.objects) do pcall(function() object:Destroy() end) end
        state.objects, state.pending = {}, {}
    end
    function state.stop()
        if state.stopped then return end
        state.stopped = true
        clearSegment()
        pcall(function() if globalEnv[KEY] == state then globalEnv[KEY] = nil end end)
        if onDone then pcall(onDone) end
    end

    local function decode(value)
        if type(value) ~= "table" then return value, true end
        local tag = value[1]
        if tag == "nil" then return nil, true end
        if tag == "ref" then
            local object = state.objects[value[2]]
            return object, object ~= nil
        end
        if tag == "num" then
            if value[2] == "inf" then return math.huge, true end
            if value[2] == "-inf" then return -math.huge, true end
            return 0/0, true
        end
        if tag == "enum" then return Enum[value[2]][value[3]], true end
        if tag == "color3" then return Color3.new(value[2], value[3], value[4]), true end
        if tag == "udim" then return UDim.new(value[2], value[3]), true end
        if tag == "udim2" then return UDim2.new(value[2], value[3], value[4], value[5]), true end
        if tag == "vector2" then return Vector2.new(value[2], value[3]), true end
        if tag == "vector3" then return Vector3.new(value[2], value[3], value[4]), true end
        if tag == "vector2i" then return Vector2int16.new(value[2], value[3]), true end
        if tag == "vector3i" then return Vector3int16.new(value[2], value[3], value[4]), true end
        if tag == "rect" then return Rect.new(value[2], value[3], value[4], value[5]), true end
        if tag == "range" then return NumberRange.new(value[2], value[3]), true end
        if tag == "brick" then return BrickColor.new(value[2]), true end
        if tag == "cframe" then return CFrame.new(table.unpack(value, 2, 13)), true end
        if tag == "font" then return Font.fromEnum(Enum.Font.Creepster), true end
        if tag == "colorseq" then
            local points = {}
            for _, p in ipairs(value[2]) do
                points[#points + 1] = ColorSequenceKeypoint.new(p[1], Color3.new(p[2], p[3], p[4]))
            end
            return ColorSequence.new(points), true
        end
        if tag == "numberseq" then
            local points = {}
            for _, p in ipairs(value[2]) do
                points[#points + 1] = NumberSequenceKeypoint.new(p[1], p[2], p[3])
            end
            return NumberSequence.new(points), true
        end
        if tag == "physical" then
            return PhysicalProperties.new(value[2], value[3], value[4], value[5], value[6]), true
        end
        return nil, false
    end
    local function safeDecode(encoded)
        local ok, value, ready = pcall(decode, encoded)
        if not ok then return nil, false end
        return value, ready
    end
    local blocked = {Active = true, Modal = true, Interactable = true, TextEditable = true}
    -- Thu nhỏ toàn bộ intro (kích thước, chữ, bo góc, viền) theo options.scale
    local SCALE = tonumber(options.scale) or 1
    state.parentOf = {}
    local function isTopLevel(id)
        local p = state.parentOf[id]
        if p == nil or p == 0 then return true end
        local pp = state.parentOf[p]
        if pp == nil or pp == 0 then return true end
        return state.parentOf[pp] == 0
    end
    local function scaleValue(id, property, value)
        if SCALE == 1 then return value end
        local t = typeof(value)
        if t == "UDim2" and (property == "Size" or (property == "Position" and not isTopLevel(id))) then
            return UDim2.new(value.X.Scale, math.floor(value.X.Offset * SCALE + 0.5), value.Y.Scale, math.floor(value.Y.Offset * SCALE + 0.5))
        elseif property == "TextSize" and type(value) == "number" then
            return math.max(6, math.floor(value * SCALE + 0.5))
        elseif t == "UDim" and (property == "CornerRadius" or property == "Padding") then
            return UDim.new(value.Scale, math.floor(value.Offset * SCALE + 0.5))
        elseif property == "Thickness" and type(value) == "number" then
            return value * SCALE
        end
        return value
    end
    local function applyProperty(id, property, encoded)
        local object = state.objects[id]
        if not object or blocked[property] then return end
        local pendingForObject = state.pending[id]
        if pendingForObject then pendingForObject[property] = nil end
        local value, ready = safeDecode(encoded)
        if not ready then
            if type(encoded) == "table" and encoded[1] == "ref" then
                state.pending[id] = state.pending[id] or {}
                state.pending[id][property] = encoded
            end
            return
        end
        local okScale, scaled = pcall(scaleValue, id, property, value)
        if okScale then value = scaled end
        pcall(function() object[property] = value end)
    end
    local function flushPending()
        for id, props in pairs(state.pending) do
            if not state.objects[id] then
                state.pending[id] = nil
            else
                for prop, encoded in pairs(props) do
                    local value, ready = safeDecode(encoded)
                    if ready then
                        pcall(function() state.objects[id][prop] = value end)
                        props[prop] = nil
                    end
                end
            end
        end
    end
    local function makeNonBlocking(object)
        pcall(function() if object:IsA("GuiObject") then object.Active = false end end)
        pcall(function() if object:IsA("GuiObject") then object.Interactable = false end end)
        pcall(function() if object:IsA("GuiButton") then object.Modal = false end end)
        pcall(function() if object:IsA("TextBox") then object.TextEditable = false end end)
    end
    local function seekSound(sound, position)
        pcall(function()
            local length = sound.TimeLength
            if length > 0 and sound.Looped then position = position % length end
            if length > 0 and not sound.Looped then position = math.min(position, math.max(0, length - 0.001)) end
            sound.TimePosition = math.max(0, position)
        end)
    end
    local function startSound(id, data)
        destroySound(id)
        local ok, sound = pcall(Instance.new, "Sound")
        if not ok or not sound then return end
        state.sounds[id] = sound
        pcall(function() sound:SetAttribute("WID_Internal_V3", true) end)
        pcall(function() sound.SoundId = data.id or "" end)
        pcall(function() sound.Volume = data.volume or 0 end)
        pcall(function() sound.PlaybackSpeed = data.speed or 1 end)
        pcall(function() sound.Looped = data.looped == true end)
        pcall(function() sound.Parent = soundService end)
        local requestedAt = os.clock()
        pcall(function() sound:Play() end)
        local startPosition = tonumber(data.position) or 0
        if startPosition > 0.001 then
            seekSound(sound, startPosition)
            local isLoaded = false
            pcall(function() isLoaded = sound.IsLoaded end)
            if not isLoaded then
                local connection
                local okConnect = pcall(function()
                    connection = sound.Loaded:Connect(function()
                        if connection then connection:Disconnect(); state.soundLoads[id] = nil end
                        if not state.stopped and state.sounds[id] == sound then
                            local speed = tonumber(data.speed) or 1
                            seekSound(sound, startPosition + (os.clock() - requestedAt) * speed)
                        end
                    end)
                end)
                if okConnect and connection then state.soundLoads[id] = connection end
            end
        end
    end
    local function apply(event)
        local op, id = event[2], event[3]
        if op == "N" then
            local ok, object = pcall(Instance.new, event[4])
            if not ok or not object then return end
            if state.objects[id] then pcall(function() state.objects[id]:Destroy() end) end
            state.objects[id] = object
            state.parentOf[id] = event[5]
            if event[5] == 0 then pcall(function() object:SetAttribute("WID_Internal_V3", true) end) end
            for property, encoded in pairs(event[6] or {}) do applyProperty(id, property, encoded) end
            for name, encoded in pairs(event[7] or {}) do
                local value, ready = safeDecode(encoded)
                if ready then pcall(function() object:SetAttribute(name, value) end) end
            end
            makeNonBlocking(object)
            local parent = event[5] == 0 and playerGui or state.objects[event[5]]
            if parent then pcall(function() object.Parent = parent end) end
            flushPending()
        elseif op == "P" then
            for property, encoded in pairs(event[4] or {}) do applyProperty(id, property, encoded) end
        elseif op == "A" then
            local object = state.objects[id]
            local value, ready = safeDecode(event[5])
            if object and ready then pcall(function() object:SetAttribute(event[4], value) end) end
        elseif op == "M" then
            local object = state.objects[id]
            local parent = event[4] == 0 and playerGui or state.objects[event[4]]
            if object and parent then state.parentOf[id] = event[4]; pcall(function() object.Parent = parent end) end
        elseif op == "D" then
            local object = state.objects[id]
            state.objects[id], state.pending[id] = nil, nil
            if object then pcall(function() object:Destroy() end) end
        elseif op == "S" then
            startSound(id, event[4] or {})
        elseif op == "U" then
            local sound = state.sounds[id]
            if sound then
                local data = event[4] or {}
                if data.volume ~= nil then pcall(function() sound.Volume = data.volume end) end
                if data.speed ~= nil then pcall(function() sound.PlaybackSpeed = data.speed end) end
                if data.looped ~= nil then pcall(function() sound.Looped = data.looped end) end
                if data.id ~= nil then pcall(function() sound.SoundId = data.id end) end
            end
        elseif op == "K" then
            local sound = state.sounds[id]
            if sound then seekSound(sound, event[4] or 0) end
        elseif op == "Q" then
            destroySound(id)
        end
    end

    task.spawn(function()
        local ok, err = xpcall(function()
            for _, segment in ipairs(segments) do
                if state.stopped then break end
                local events = segment.events or {}
                local duration = math.max(0, tonumber(segment.duration) or 0)
                local startedAt, index = os.clock(), 1
                while not state.stopped do
                    if state.skipping then break end
                    local elapsed = os.clock() - startedAt
                    while index <= #events and (tonumber(events[index][1]) or 0) <= elapsed do
                        apply(events[index])
                        index = index + 1
                    end
                    if elapsed >= duration and index > #events then break end
                    runService.Heartbeat:Wait()
                end
                if state.skipping then
                    while not state.stopped do runService.Heartbeat:Wait() end
                    break
                end
                clearSegment()
            end
        end, function(message) return tostring(message) end)
        if not ok then warn("[Ghost Duel Intro] Playback stopped: " .. tostring(err)) end
        state.stop()
    end)
    return state
end

	-- Chặn phần script chính cho đến khi người dùng bấm SKIP.
	local ghostIntroContinue = Instance.new("BindableEvent")
	local ghostIntroWasSkipped = false
	local ghostIntroEnded = false

	-- Gỡ màn đen đúng lúc intro kết thúc hoặc khi người dùng bấm SKIP.
	local function finishGhostIntroBlackScreen()
		if ghostIntroEnded then return end
		ghostIntroEnded = true
		pcall(function()
			if ghostIntroBlackCover and ghostIntroBlackCover.Parent then
				ghostIntroBlackCover:Destroy()
			end
		end)
		pcall(function() ghostIntroContinue:Fire() end)
	end

	--============================================================
	-- START INTRO
	--============================================================
	task.spawn(function()
		local ok, err = pcall(function()
			local logoTop = embeddedAsset("GhostDuelIntro_LogoTop_" .. IMG_VERSION .. ".png", LOGO_TOP_B64)
			local logoBottom = embeddedAsset("GhostDuelIntro_LogoBottom_" .. IMG_VERSION .. ".png", LOGO_BOTTOM_B64)
			local paper = embeddedAsset("GhostDuelIntro_Paper_" .. IMG_VERSION .. ".png", PAPER_B64)
			local music = (MUSIC_ID ~= "" and MUSIC_ID) or loadUrlAsset(MUSIC_URL, MUSIC_FILE) or ""

			-- Dời chữ "Ghost Duel" sang bên phải nhân vật ở giữa
			local ghostDuelIds = {}
			local function moveOnTop(pos)
				if type(pos) == "table" and pos[1] == "udim2" then pos[2] = GHOST_DUEL_X end
			end

			for _, segment in ipairs(_segments) do
				for _, ev in ipairs(segment.events or {}) do
					local op = ev[2]
					if op == "P" and ghostDuelIds[ev[3]] and type(ev[4]) == "table" then
						moveOnTop(ev[4].Position)
					end
					if op == "N" and type(ev[6]) == "table" then
						local props = ev[6]
						if props.Image == ORIGINAL_LOGO_BOTTOM then
							ghostDuelIds[ev[3]] = true
							moveOnTop(props.Position)
						end
						if props.Name == "SpotifyFrame" then
							props.Visible = false -- ẩn khung nhạc góc phải
						end
						if ev[4] == "ScreenGui" and ev[5] == 0 then
							props.Name = "GhostDuelIntro"
							props.DisplayOrder = 999999
						end
						local img = props.Image
						if type(img) == "string" then
							if img == ORIGINAL_LOGO_TOP and logoTop then
								props.Image = logoTop
							elseif img == ORIGINAL_LOGO_BOTTOM and logoBottom then
								props.Image = logoBottom
							elseif img == ORIGINAL_PAPER and paper then
								props.Image = paper
							elseif string.sub(img, 1, 9) == "rbxasset:" and string.sub(img, 1, 12) ~= "rbxassetid:/" then
								props.Image = "" -- file riêng của máy người làm intro gốc, không dùng được
							end
						end
					elseif op == "S" and type(ev[4]) == "table" then
						ev[4].id = music
						ev[4].volume = MUSIC_VOLUME
						ev[4].position = MUSIC_START
						ev[4].looped = false
					elseif op == "U" and type(ev[4]) == "table" and ev[4].volume ~= nil then
						ev[4].volume = (ev[4].volume / 10) * MUSIC_VOLUME
					end
				end
			end

			local state = playTimeline(_segments, { target = PlayerGui, scale = INTRO_SCALE })

			-- Nút SKIP riêng ở góc trên bên phải; không bỏ qua khi chạm màn hình bên ngoài.
			if ALLOW_SKIP and state then
				local skipGui = Instance.new("ScreenGui")
				skipGui.Name = "GhostDuelIntroSkip"
				skipGui.ResetOnSpawn = false
				skipGui.IgnoreGuiInset = true
				skipGui.DisplayOrder = 1000000
				skipGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
				skipGui.Parent = PlayerGui

				local skipButton = Instance.new("TextButton")
				skipButton.Name = "SkipButton"
				skipButton.AnchorPoint = Vector2.new(1, 0)
				skipButton.Position = UDim2.new(1, -22, 0, 22)
				skipButton.Size = UDim2.new(0, 88, 0, 34)
				skipButton.BackgroundColor3 = Color3.fromRGB(22, 23, 28)
				skipButton.BackgroundTransparency = 0.12
				skipButton.BorderSizePixel = 0
				skipButton.AutoButtonColor = true
				skipButton.Text = "SKIP  ›"
				skipButton.TextColor3 = Color3.fromRGB(245, 245, 250)
				skipButton.TextSize = 13
				skipButton.Font = Enum.Font.GothamBold
				skipButton.ZIndex = 1000001
			skipButton.Parent = skipGui

				local skipCorner = Instance.new("UICorner")
				skipCorner.CornerRadius = UDim.new(0, 9)
				skipCorner.Parent = skipButton
				local skipStroke = Instance.new("UIStroke")
				skipStroke.Color = Color3.fromRGB(205, 208, 218)
				skipStroke.Thickness = 1.25
				skipStroke.Transparency = 0.12
				skipStroke.Parent = skipButton

				local originalStop = state.stop
				state.stop = function()
					-- Khi intro chạy hết tự nhiên, gỡ màn đen và cho script tiếp tục.
					finishGhostIntroBlackScreen()
					if ghostIntroWasSkipped and skipGui and skipGui.Parent then skipGui:Destroy() end
					originalStop()
				end

				local skipping = false
				skipButton.Activated:Connect(function()
					if skipping or state.skipping then return end
					skipping = true
					ghostIntroWasSkipped = true
					finishGhostIntroBlackScreen()
					state.skipping = true
					local info = TweenInfo.new(0.35, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
					for _, obj in pairs(state.objects) do
						pcall(function()
							if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
								TS:Create(obj, info, { ImageTransparency = 1, BackgroundTransparency = 1 }):Play()
							elseif obj:IsA("TextLabel") or obj:IsA("TextButton") then
								TS:Create(obj, info, { TextTransparency = 1, BackgroundTransparency = 1 }):Play()
							elseif obj:IsA("Frame") then
								TS:Create(obj, info, { BackgroundTransparency = 1 }):Play()
							elseif obj:IsA("UIStroke") then
								TS:Create(obj, info, { Transparency = 1 }):Play()
							end
						end)
					end
					for _, snd in pairs(state.sounds) do
						pcall(function() TS:Create(snd, info, { Volume = 0 }):Play() end)
					end
					pcall(function() TS:Create(skipButton, info, { BackgroundTransparency = 1, TextTransparency = 1 }):Play() end)
					pcall(function() TS:Create(skipStroke, info, { Transparency = 1 }):Play() end)
				task.delay(0.4, function() pcall(state.stop) end)
				end)
			end

		end)
		if not ok then
			warn("[Ghost Duel Intro] " .. tostring(err))
			finishGhostIntroBlackScreen()
			pcall(function()
				local g = PlayerGui:FindFirstChild("GhostDuelIntro")
				if g then g:Destroy() end
			end)
		end
	end)
	-- Chờ intro kết thúc tự nhiên hoặc người dùng bấm SKIP.
	if not ghostIntroEnded then
		ghostIntroContinue.Event:Wait()
	end
	pcall(function() ghostIntroContinue:Destroy() end)
	pcall(function()
		if ghostIntroBlackCover and ghostIntroBlackCover.Parent then
			ghostIntroBlackCover:Destroy()
		end
	end)
end

end -- GhostDuelIntroEnabled
