mkSect(songPage,"ghost Songs")
do
    local ghost_SONGS = {
        {"Brasil", "rbxassetid://91225667489242"},
        {"Brasil x2", "rbxassetid://135750430892149"},
        {"Tryhard 2", "rbxassetid://77142753938657"},
        {"Tryhard Definitivo", "rbxassetid://75196377290071"},
    }
    local musicPaused = false
    local pauseButton

    local function playghostSong(song)
        stopCurrentMusic()
        local sound = Instance.new("Sound")
        sound.Name = "ghostHubSong"
        sound.SoundId = song[2]
        sound.Volume = 0.7
        sound.Looped = true
        sound.Parent = SoundService
        ghostCurrentMusicSound = sound
        musicPaused = false
        if pauseButton then pauseButton.Text = "Pausar" end
        pcall(function() sound:Play() end)
    end

    for _, song in ipairs(ghost_SONGS) do
        local row = mkRow(songPage, 46)
        local btn = ghostUI.new("TextButton", row, {
            Size = UDim2.new(1, -12, 1, -8),
            Position = UDim2.fromOffset(6, 4),
            Text = song[1],
            TextSize = 14,
            Font = Enum.Font.GothamBold,
            TextColor3 = Color3.fromRGB(255, 255, 255),
            BackgroundColor3 = Color3.fromRGB(0,0,0),
            BorderSizePixel = 0,
            AutoButtonColor = false,
            ZIndex = 8,
        })
        ghostUI.round(btn, 8)
        ghostUI.stroke(btn, Color3.fromRGB(255, 255, 255), 0.35, 1)
        btn.Activated:Connect(function()
            playghostSong(song)
        end)
    end

    local controlsRow = mkRow(songPage, 44)
    pauseButton = ghostUI.new("TextButton", controlsRow, {
        Size = UDim2.new(0.5, -9, 1, -8),
        Position = UDim2.fromOffset(6, 4),
        Text = "Pausar",
        TextSize = 13,
        Font = Enum.Font.GothamBold,
        TextColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundColor3 = Color3.fromRGB(0,0,0),
        BorderSizePixel = 0,
        AutoButtonColor = false,
        ZIndex = 8,
    })
    ghostUI.round(pauseButton, 8)
    ghostUI.stroke(pauseButton, Color3.fromRGB(255, 255, 255), 0.35, 1)
    pauseButton.Activated:Connect(function()
        local sound = ghostCurrentMusicSound
        if not sound or not sound.Parent then return end
        local ok = pcall(function()
            if musicPaused then
                sound:Resume()
            else
                sound:Pause()
            end
        end)
        if ok then
            musicPaused = not musicPaused
            pauseButton.Text = musicPaused and "Reanudar" or "Pausar"
        end
    end)

    local stopButton = ghostUI.new("TextButton", controlsRow, {
        Size = UDim2.new(0.5, -9, 1, -8),
        Position = UDim2.new(0.5, 3, 0, 4),
        Text = "Detener",
        TextSize = 13,
        Font = Enum.Font.GothamBold,
        TextColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundColor3 = Color3.fromRGB(0,0,0),
        BorderSizePixel = 0,
        AutoButtonColor = false,
        ZIndex = 8,
    })
    ghostUI.round(stopButton, 8)
    ghostUI.stroke(stopButton, Color3.fromRGB(255, 255, 255), 0.35, 1)
    stopButton.Activated:Connect(function()
        stopCurrentMusic()
        musicPaused = false
        pauseButton.Text = "Pausar"
