-- GHOST DUEL STARTUP: invoke the UI builders after all functions are defined.
task.spawn(function()
    local ok, err = pcall(buildGui)
    if not ok then
        warn("[Ghost Duel] buildGui failed: " .. tostring(err))
    end

    local mobileOk, mobileErr = pcall(createMobilePanel)
    if not mobileOk then
        warn("[Ghost Duel] createMobilePanel failed: " .. tostring(mobileErr))
    end
end)

--============================================================
-- GHOST DUEL BLACK / WHITE FINISH + FLOATING GHOST DECORATIONS
-- Half-white / half-black logo, monochrome menu, gentle ghost motion.
--============================================================
task.spawn(function()
    local deadline = os.clock() + 15
    repeat task.wait(0.15) until (main and main.Parent and gui and gui.Parent) or os.clock() > deadline
    if not (main and main.Parent and gui and gui.Parent) then return end

    local BLACK = Color3.fromRGB(0, 0, 0)
    local WHITE = Color3.fromRGB(255, 255, 255)

    local function gray(c)
        local v = math.clamp(0.299 * c.R + 0.587 * c.G + 0.114 * c.B, 0, 1)
        return Color3.new(v, v, v)
    end
    local function graySequence(sequence)
        local points = {}
        for _, point in ipairs(sequence.Keypoints) do
            points[#points + 1] = ColorSequenceKeypoint.new(point.Time, gray(point.Value))
        end
        return ColorSequence.new(points)
    end

    -- Remove all green/colored accents from the Main Menu and make it monochrome.
    pcall(function()
        main.BackgroundColor3 = BLACK
        local bg = main:FindFirstChild("BackgroundImage")
        -- Keep the custom image visible beneath the dark overlay.
        if bg and bg:IsA("ImageLabel") then bg.ImageTransparency = 0.12 end
        local veil = main:FindFirstChild("BackgroundVeil")
        if veil then veil.BackgroundColor3 = BLACK; veil.BackgroundTransparency = 0.48 end
        local header = main:FindFirstChild("ScriptHeader")
        if header then header.BackgroundColor3 = BLACK end
        for _, obj in ipairs(main:GetDescendants()) do
            pcall(function()
                if obj:IsA("GuiObject") then
                    obj.BackgroundColor3 = gray(obj.BackgroundColor3)
                end
                if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
                    obj.TextColor3 = gray(obj.TextColor3)
                    obj.TextStrokeColor3 = gray(obj.TextStrokeColor3)
                end
                if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
                    obj.ImageColor3 = gray(obj.ImageColor3)
                end
                if obj:IsA("UIStroke") then obj.Color = gray(obj.Color) end
                if obj:IsA("UIGradient") then obj.Color = graySequence(obj.Color) end
            end)
        end
        local scene = header and header:FindFirstChild("Scene")
        if scene and scene:IsA("ImageLabel") then scene.ImageTransparency = 1 end
        local artworkShade = header and header:FindFirstChild("ArtworkShade")
        if artworkShade then artworkShade.BackgroundColor3 = BLACK; artworkShade.BackgroundTransparency = 0.02 end
        local badge = header and header:FindFirstChild("Edition")
        if badge then badge.BackgroundColor3 = BLACK end
        local panelInset = main:FindFirstChild("PanelInset")
        if panelInset then
            for _, stroke in ipairs(panelInset:GetChildren()) do
                if stroke:IsA("UIStroke") then stroke.Color = WHITE; stroke.Transparency = 0.78 end
            end
        end
    end)

    -- Rebuild the title as dedicated labels so it cannot disappear with old artwork.
    local header = main:FindFirstChild("ScriptHeader")
    if header then
        local oldTitle = header:FindFirstChild("GhostDuelVisibleTitle")
        if oldTitle then oldTitle:Destroy() end
        local logo = Instance.new("TextLabel")
        logo.Name = "GhostDuelVisibleTitle"
        logo.BackgroundTransparency = 1
        logo.BorderSizePixel = 0
        logo.Position = UDim2.fromOffset(11, 18)
        logo.Size = UDim2.new(1, -88, 0, 39)
        logo.Font = Enum.Font.LuckiestGuy
        logo.Text = "GHOST DUEL"
        logo.TextSize = 28
        logo.TextScaled = false
        logo.TextWrapped = false
        logo.TextXAlignment = Enum.TextXAlignment.Left
        logo.TextYAlignment = Enum.TextYAlignment.Center
        logo.TextColor3 = WHITE
        logo.TextStrokeColor3 = WHITE
        logo.TextStrokeTransparency = 0
        logo.Visible = true
        logo.ZIndex = 40
        logo.Parent = header
        local split = Instance.new("UIGradient")
        split.Name = "HalfWhiteHalfBlack"
        split.Rotation = 0
        split.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, WHITE),
            ColorSequenceKeypoint.new(0.49, WHITE),
            ColorSequenceKeypoint.new(0.51, BLACK),
            ColorSequenceKeypoint.new(1, BLACK),
        })
        split.Parent = logo
    end

    -- Draw a new custom sheet-ghost (not the standard 👻 emoji).
    -- The rounded head/body and three scallops create a small ghost silhouette.
    local function addFloatingGhost(parent, name, position, size, zIndex, transparency, xDrift, yDrift)
        local holder = Instance.new("Frame")
        holder.Name = name
        holder.BackgroundTransparency = 1
        holder.BorderSizePixel = 0
        holder.Size = UDim2.fromOffset(size + 10, size + 12)
        holder.Position = position
        holder.Rotation = -8
        holder.ZIndex = zIndex or 5
        holder.Active = false
        holder.Selectable = false
        holder.Parent = parent

        local alpha = transparency or 0.18
        local body = Instance.new("Frame")
        body.Name = "GhostBody"
        body.AnchorPoint = Vector2.new(0.5, 0)
        body.Position = UDim2.new(0.5, 0, 0, 1)
        body.Size = UDim2.new(0.78, 0, 0.78, 0)
        body.BackgroundColor3 = WHITE
        body.BackgroundTransparency = alpha
        body.BorderSizePixel = 0
        body.ZIndex = holder.ZIndex
        body.Parent = holder
        local bodyCorner = Instance.new("UICorner")
        bodyCorner.CornerRadius = UDim.new(0.48, 0)
        bodyCorner.Parent = body
        local bodyStroke = Instance.new("UIStroke")
        bodyStroke.Color = BLACK
        bodyStroke.Transparency = 0.12
        bodyStroke.Thickness = 1
        bodyStroke.Parent = body

        for i = 1, 3 do
            local foot = Instance.new("Frame")
            foot.Name = "GhostTail" .. i
            foot.AnchorPoint = Vector2.new(0.5, 0.5)
            foot.Position = UDim2.new((i - 1) * 0.34 + 0.16, 0, 0.78, 0)
            foot.Size = UDim2.new(0.36, 0, 0.34, 0)
            foot.BackgroundColor3 = WHITE
            foot.BackgroundTransparency = alpha
            foot.BorderSizePixel = 0
            foot.ZIndex = holder.ZIndex + 1
            foot.Parent = body
            local corner = Instance.new("UICorner")
            corner.CornerRadius = UDim.new(1, 0)
            corner.Parent = foot
        end

        for i = 1, 2 do
            local eye = Instance.new("Frame")
            eye.Name = "Eye" .. i
