                    base.X.Scale, base.X.Offset + (xDrift or 5) * direction,
                    base.Y.Scale, base.Y.Offset + (yDrift or 10) * direction
                )
                local tween = TS:Create(holder, TweenInfo.new(1.8 + (size % 5) * 0.12, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                    Position = target,
                    Rotation = direction == 1 and 8 or -8,
                })
                tween:Play()
                tween.Completed:Wait()
                direction = -direction
                task.wait(0.05)
