        if border then border.Color = WHITE; border.Transparency = 0.1 end
    end

    -- New ghost style: a compact outlined "sheet ghost" with a wavy hem.
    -- All ghosts are small and placed in margins/corners, never over labels.
    local function makeNewGhost(parent, name, pos, size, z, alpha)
        local holder = Instance.new("Frame")
        holder.Name = name
        holder.BackgroundTransparency = 1
        holder.BorderSizePixel = 0
        holder.Position = pos
        holder.Size = UDim2.fromOffset(size, size + 5)
