        local outline = Instance.new("UIStroke")
        outline.Color = WHITE
        outline.Thickness = 1.5
        outline.Transparency = alpha or 0.08
        outline.Parent = dome

        for i = 1, 3 do
            local wave = Instance.new("Frame")
            wave.Name = "Hem" .. i
            wave.AnchorPoint = Vector2.new(0.5, 0)
            wave.Position = UDim2.new((i - 1) * 0.29 + 0.20, 0, 0.61, 0)
            wave.Size = UDim2.new(0.34, 0, 0.25, 0)
            wave.BackgroundColor3 = BLACK
            wave.BackgroundTransparency = 0.12
            wave.BorderSizePixel = 0
            wave.ZIndex = z
            wave.Parent = holder
            local c = Instance.new("UICorner")
            c.CornerRadius = UDim.new(1, 0)
            c.Parent = wave
            local st = Instance.new("UIStroke")
            st.Color = WHITE
            st.Thickness = 1.25
            st.Transparency = alpha or 0.08
            st.Parent = wave
        end

        for i = 1, 2 do
            local eye = Instance.new("Frame")
            eye.Name = "Eye" .. i
            eye.AnchorPoint = Vector2.new(0.5, 0.5)
            eye.Position = UDim2.new(i == 1 and 0.38 or 0.62, 0, 0.43, 0)
            eye.Size = UDim2.fromOffset(2, 4)
            eye.BackgroundColor3 = WHITE
            eye.BorderSizePixel = 0
            eye.ZIndex = z + 1
            eye.Parent = dome
            local c = Instance.new("UICorner")
            c.CornerRadius = UDim.new(1, 0)
            c.Parent = eye
        end

        task.spawn(function()
            local base = pos
            local sign = 1
            while holder.Parent do
                local tw = TS:Create(holder, TweenInfo.new(2.1, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                    Position = UDim2.new(base.X.Scale, base.X.Offset + 3 * sign, base.Y.Scale, base.Y.Offset + 4 * sign),
                    Rotation = sign * 5,
                })
                tw:Play()
                tw.Completed:Wait()
                sign = -sign
            end
        end)
        return holder
    end

    local insideLayer = Instance.new("Frame")
    insideLayer.Name = "GhostDuelNewInsideGhosts"
    insideLayer.BackgroundTransparency = 1
    insideLayer.BorderSizePixel = 0
    insideLayer.Size = UDim2.fromScale(1, 1)
    insideLayer.Position = UDim2.fromScale(0, 0)
    insideLayer.ClipsDescendants = true
    insideLayer.ZIndex = 3
    insideLayer.Parent = main
    makeNewGhost(insideLayer, "InsideGhostLeftBottom", UDim2.new(0, 5, 1, -42), 24, 3, 0.25)
    makeNewGhost(insideLayer, "InsideGhostRightBottom", UDim2.new(1, -31, 1, -42), 24, 3, 0.25)

