        outerLayer.Size = UDim2.fromOffset(sz.X + 50, sz.Y + 50)
        outerLayer.Visible = main.Visible
    end
    updateOuter()
    main:GetPropertyChangedSignal("AbsolutePosition"):Connect(updateOuter)
    main:GetPropertyChangedSignal("AbsoluteSize"):Connect(updateOuter)
    main:GetPropertyChangedSignal("Visible"):Connect(updateOuter)
    makeNewGhost(outerLayer, "OuterGhostTopLeft", UDim2.fromOffset(0, 10), 20, 12, 0.12)
    makeNewGhost(outerLayer, "OuterGhostTopRight", UDim2.new(1, -22, 0, 12), 20, 12, 0.12)

