        bg.Parent = main
    end
    bg.AnchorPoint = Vector2.new(0, 0)
    bg.Position = UDim2.fromScale(0, 0)
    bg.Size = UDim2.fromScale(1, 1)
    bg.BackgroundTransparency = 1
    bg.BorderSizePixel = 0
    bg.Image = customBackground
    bg.ImageTransparency = 0.10
    -- Ask Roblox to preload the image as soon as the ImageLabel is configured.
    -- This removes the artificial delay; actual network/asset permission delays may still occur.
    pcall(function()
        game:GetService("ContentProvider"):PreloadAsync({bg})
    end)
    if not (main and main.Parent and bg and bg.Parent) then return end
    bg.ImageColor3 = Color3.fromRGB(255, 255, 255)
    bg.ScaleType = Enum.ScaleType.Crop
    bg.Visible = true
    bg.ZIndex = 1
    bg.Active = false

    -- Keep a light dark veil for readability, but never let it cover the image.
    local veil = main:FindFirstChild("BackgroundVeil")
    if veil and veil:IsA("Frame") then
        veil.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        veil.BackgroundTransparency = 0.48
        veil.ZIndex = 2
    end
    if ghostUI and ghostUI.art and ghostUI.art.Parent then
        ghostUI.art.Image = customBackground
        ghostUI.art.ImageTransparency = 0.18
        ghostUI.art.ImageColor3 = Color3.fromRGB(255, 255, 255)
    end

    -- Keep the image behind all menu controls and text.
    pcall(function()
        local corner = bg:FindFirstChildOfClass("UICorner")
        if not corner then
            corner = Instance.new("UICorner")
            corner.Parent = bg
        end
        corner.CornerRadius = UDim.new(0, 18)
    end)
end)
